function archiveCurrentConversation(){if(!state.messages.length)return;state.history.unshift({id:Date.now(),title:(state.messages.find(m=>m.role==='user')?.text||'Conversație nouă').slice(0,72),date:new Date().toLocaleString(),messages:state.messages.slice(-40)});state.history=state.history.slice(0,30);saveHistory()}
