function locationErrorMessage(err){return new Error(err&&err.code===1?'Permisiunea de localizare a fost refuzată. Activează locația pentru acest site.':err&&err.code===3?'Localizarea a expirat. Încearcă din nou.':'Nu am putut obține coordonatele GPS.')}
function startSharedLocation(){if(state.locationStarted)return;state.locationStarted=true;if(!navigator.geolocation){console.info('myPocket AI: geolocația nu este disponibilă în acest browser.');return}navigator.geolocation.getCurrentPosition(pos=>{saveLocation({latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy});},err=>{console.info('myPocket AI: localizarea inițială nu a reușit:',locationErrorMessage(err).message);},{enableHighAccuracy:true,timeout:15000,maximumAge:60000});state.locationWatchId=navigator.geolocation.watchPosition(pos=>{saveLocation({latitude:pos.coords.latitude,longitude:pos.coords.longitude,accuracy:pos.coords.accuracy});},err=>{console.info('myPocket AI: actualizarea locației nu este disponibilă:',locationErrorMessage(err).message);},{enableHighAccuracy:true,timeout:20000,maximumAge:5000});}
async function getCurrentCoordinates(forceRefresh=false){if(!forceRefresh&&state.location&&Date.now()-state.location.updatedAt<120000&&Number.isFinite(state.location.latitude)&&Number.isFinite(state.location.longitude))return {latitude:state.location.latitude,longitude:state.location.longitude,accuracy:state.location.accuracy};if(!navigator.geolocation)throw new Error('Acest browser nu oferă acces la GPS.');let lastError=null;for(let attempt=0;attempt<2;attempt++){try{return await new Promise((resolve,reject)=>navigator.geolocation.getCurrentPosition(pos=>{const c=pos&&pos.coords;if(!c||!Number.isFinite(c.latitude)||!Number.isFinite(c.longitude)||Math.abs(c.latitude)>90||Math.abs(c.longitude)>180){reject(new Error('Browserul nu a furnizat coordonate GPS valide.'));return}saveLocation({latitude:c.latitude,longitude:c.longitude,accuracy:Number.isFinite(c.accuracy)?c.accuracy:null});resolve({latitude:state.location.latitude,longitude:state.location.longitude,accuracy:state.location.accuracy})},err=>reject(locationErrorMessage(err)),{enableHighAccuracy:true,timeout:20000,maximumAge:0}))}catch(err){lastError=err;if(err&&err.message&&err.message.includes('refuzată'))throw err}}throw lastError||new Error('Nu am putut obține coordonatele GPS.');}
function needsLocation(text){return /(unde sunt|localiz\\w*|geolocaliz\\w*|locația mea|locatia mea|în jurul meu|in jurul meu|în apropiere|in apropiere|în apropierea mea|in apropierea mea|în zona mea|in zona mea|pe lângă mine|pe langa mine|aproape de mine|near me|nearby|around me|around here|near here|close to me|my location)/i.test(text);}
// 07 — Chat transport. Voice errors never convert a successful API response into request failure.
async function submitMessage({fromVoice=false}={}){if(state.busy)return;const message=inputEl.value.trim();if(!message)return;if(message.length>CLIENT_CONFIG.maxMessageLength){notify('Mesajul este prea lung.');return}state.busy=true;const generation=state.conversationGeneration;sendBtn.disabled=true;inputEl.disabled=true;setStatus('myPocket AI pregătește răspunsul…');addBubble(message,'user');state.messages.push({role:'user',text:message});inputEl.value='';const loading=addBubble('Se pregătește răspunsul…','assistant');try{const history=state.messages.slice(-CLIENT_CONFIG.historyLimit).map(m=>({role:m.role,content:m.text}));const locationIntent=needsLocation(message);let coordinates=null;let locationErrorText=null;if(state.location&&Number.isFinite(state.location.latitude)&&Number.isFinite(state.location.longitude)){coordinates={latitude:state.location.latitude,longitude:state.location.longitude,accuracy:state.location.accuracy,updatedAt:state.location.updatedAt}}if(navigator.geolocation){getCurrentCoordinates(true).catch(locationError=>{console.info('myPocket AI: actualizarea locației continuă în fundal:',String(locationError&&locationError.message||locationError));});}else{locationErrorText='Acest browser nu oferă acces la geolocalizare.'}if(locationIntent&&!coordinates){locationErrorText=locationErrorText||'Nu există încă o poziție disponibilă; cererea este trimisă fără coordonate.';setStatus('Caut răspunsul; locația se actualizează în fundal.')}const response=await fetch(CLIENT_CONFIG.apiUrl,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message,language:state.language,history,location_requested:locationIntent,location:coordinates,coordinates,location_error:locationIntent&&!coordinates?(locationErrorText||'Nu s-au obținut coordonate GPS valide.'):undefined})});let data;try{data=await response.json()}catch{throw new Error(state.language==='en'?'The server returned an unreadable response.':'Serverul a trimis un răspuns care nu poate fi citit.')}if(!response.ok||data.status!=='success'||typeof data.reply!=='string'||!data.reply.trim())throw new Error(data.error||data.message||('Serverul nu a returnat un răspuns utilizabil (HTTP '+response.status+').'));const reply=String(data.reply).trim();loading.remove();if(generation!==state.conversationGeneration||(state.currentView!=='assistant'&&state.currentView!=='module'))return;addBubble(reply,'assistant');state.messages.push({role:'assistant',text:reply});state.lastReply=reply;state.messages=state.messages.slice(-40);setStatus('Răspuns primit.');if(state.voiceMode||fromVoice){speakText(reply,{continuous:state.voiceMode})}else if(state.messages.length===2){/* first reply only: text remains the default */}}catch(error){loading.remove();if(generation===state.conversationGeneration&&(state.currentView==='assistant'||state.currentView==='module')){const messageText=String(error?.message||'Eroare necunoscută.');addBubble('Nu am putut obține un răspuns. '+messageText,'assistant',true);setStatus('Cererea nu a reușit.');console.error('myPocket AI chat request failed:',error)}}finally{state.busy=false;sendBtn.disabled=false;inputEl.disabled=false;if(state.voiceMode){inputEl.blur()}else inputEl.focus()}}
$('chatForm').addEventListener('submit',event=>{event.preventDefault();submitMessage()});inputEl.addEventListener('keydown',event=>{if(event.key==='Enter'&&!event.shiftKey){event.preventDefault();$('chatForm').requestSubmit()}});inputEl.addEventListener('input',()=>{inputEl.style.height='auto';inputEl.style.height=Math.min(inputEl.scrollHeight,130)+'px'});
$('newChatBtn').addEventListener('click',()=>{if(state.busy){notify('Așteaptă să se termine răspunsul curent.');return}archiveCurrentConversation();resetChat();notify('Ai început o conversație nouă.')});
